import{_ as o,o as e,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Glossario","description":"","frontmatter":{"status":"ativo","tipo":"glossario","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"planejamento/adocao/glossario.md","filePath":"planejamento/adocao/glossario.md","lastUpdated":null}'),t={name:"planejamento/adocao/glossario.md"};function s(l,a,c,n,d,p){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="glossario" tabindex="-1">Glossario <a class="header-anchor" href="#glossario" aria-label="Permalink to &quot;Glossario&quot;">​</a></h1><h2 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h2><p>Classe em <code>app/Actions</code> responsavel por executar regra de negocio ou mudanca de estado.</p><h2 id="administracao" tabindex="-1">Administracao <a class="header-anchor" href="#administracao" aria-label="Permalink to &quot;Administracao&quot;">​</a></h2><p>Modulo privado para usuarios, cargos, permissoes, calendario, atividades, tarefas e revisao de formularios.</p><h2 id="auto-dj" tabindex="-1">Auto DJ <a class="header-anchor" href="#auto-dj" aria-label="Permalink to &quot;Auto DJ&quot;">​</a></h2><p>Execucao automatica de programacao da radio quando nao ha locucao ao vivo.</p><h2 id="ciclo" tabindex="-1">Ciclo <a class="header-anchor" href="#ciclo" aria-label="Permalink to &quot;Ciclo&quot;">​</a></h2><p>Periodo de acompanhamento operacional, normalmente mensal ou por sprint.</p><h2 id="controller-de-pagina" tabindex="-1">Controller de Pagina <a class="header-anchor" href="#controller-de-pagina" aria-label="Permalink to &quot;Controller de Pagina&quot;">​</a></h2><p>Controller em <code>app/Http/Controllers/Private/Pages</code> ou <code>Public/Pages</code> responsavel por renderizar uma pagina Inertia.</p><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>Classe em <code>app/Filters</code> que centraliza consultas e filtros de listagem.</p><h2 id="guia-operacional" tabindex="-1">Guia Operacional <a class="header-anchor" href="#guia-operacional" aria-label="Permalink to &quot;Guia Operacional&quot;">​</a></h2><p>Nota voltada para uso do sistema, com foco em fluxo, resultado esperado e cuidados.</p><h2 id="inertia" tabindex="-1">Inertia <a class="header-anchor" href="#inertia" aria-label="Permalink to &quot;Inertia&quot;">​</a></h2><p>Camada que conecta controllers Laravel com paginas Svelte.</p><h2 id="invokes" tabindex="-1">Invokes <a class="header-anchor" href="#invokes" aria-label="Permalink to &quot;Invokes&quot;">​</a></h2><p>Controllers invocaveis usados para acoes especificas que nao sao CRUD padrao.</p><h2 id="locucao" tabindex="-1">Locucao <a class="header-anchor" href="#locucao" aria-label="Permalink to &quot;Locucao&quot;">​</a></h2><p>Modulo de operacao ao vivo da radio, usado para iniciar e finalizar transmissao e controlar pedidos.</p><h2 id="modulo" tabindex="-1">Modulo <a class="header-anchor" href="#modulo" aria-label="Permalink to &quot;Modulo&quot;">​</a></h2><p>Area funcional do painel ou do produto, como Radio, Postagens, Midias ou Administracao.</p><h2 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h2><p>Ferramenta usada para publicar a documentação Markdown como site navegável.</p><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><p>Classe em <code>app/Policies</code> que controla autorizacao por modelo ou recurso.</p><h2 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h2><p>Classe em <code>app/Http/Resources</code> que formata dados enviados para o frontend.</p><h2 id="site-estatico" tabindex="-1">Site Estático <a class="header-anchor" href="#site-estatico" aria-label="Permalink to &quot;Site Estático&quot;">​</a></h2><p>Versão gerada pelo VitePress em HTML, CSS e JavaScript para publicação.</p>',31)])])}const m=o(t,[["render",s]]);export{h as __pageData,m as default};
